            window.resetDropdown = function(id, defaultText) {
                const el = document.getElementById(id);
                el.innerHTML = '<option value="" disabled selected>' + defaultText + '</option>';
                el.disabled = true;
                el.value = "";
                el.classList.add('bg-gray-50', 'text-gray-500');
                el.classList.remove('bg-white', 'text-gray-900');
            }

            window.populateDropdown = function(id, dataObj) {
                const el = document.getElementById(id);
                for(let key in dataObj) {
                    if (key === 'nama') continue; // skip the 'nama' prop which holds the parent name
                    let option = document.createElement("option");
                    option.value = key;
                    // if the child is an object, its text is obj.nama, else it's just the string value
                    option.text = (typeof dataObj[key] === 'object' && dataObj[key].nama) ? dataObj[key].nama : (typeof dataObj[key] === 'object' ? key : dataObj[key]);
                    // Hotfix: if dataObj[key] is string it means it's a village
                    if (typeof dataObj[key] === 'string') {
                        option.text = dataObj[key];
                    }
                    el.appendChild(option);
                }
                el.disabled = false;
                el.classList.remove('bg-gray-50', 'text-gray-500');
                el.classList.add('bg-white', 'text-gray-900');
            }

            window.updateKabupaten = function() {
                resetDropdown('kabupaten', '-- Pilih Kabupaten --');
                resetDropdown('kecamatan', '-- Pilih Kecamatan --');
                resetDropdown('desa', '-- Pilih Desa --');
                villageCard.classList.add('hidden');
                hidKodeDesa.value = '';
                
                const provVal = document.getElementById('provinsi').value;
                if(provVal && dataWilayah[provVal]) {
                    populateDropdown('kabupaten', dataWilayah[provVal].kabupaten);
                    hidProvinsi.value = dataWilayah[provVal].nama;
                }
            }

            window.updateKecamatan = function() {
                resetDropdown('kecamatan', '-- Pilih Kecamatan --');
                resetDropdown('desa', '-- Pilih Desa --');
                villageCard.classList.add('hidden');
                hidKodeDesa.value = '';
                
                const provVal = document.getElementById('provinsi').value;
                const kabVal = document.getElementById('kabupaten').value;
                if(kabVal && dataWilayah[provVal].kabupaten[kabVal]) {
                    populateDropdown('kecamatan', dataWilayah[provVal].kabupaten[kabVal].kecamatan);
                    hidKabupaten.value = dataWilayah[provVal].kabupaten[kabVal].nama.replace(/ \([0-9]+\)/, '');
                }
            }

            window.updateDesa = function() {
                resetDropdown('desa', '-- Pilih Desa --');
                villageCard.classList.add('hidden');
                hidKodeDesa.value = '';
                
                const provVal = document.getElementById('provinsi').value;
                const kabVal = document.getElementById('kabupaten').value;
                const kecVal = document.getElementById('kecamatan').value;
                if(kecVal && dataWilayah[provVal].kabupaten[kabVal].kecamatan[kecVal]) {
                    populateDropdown('desa', dataWilayah[provVal].kabupaten[kabVal].kecamatan[kecVal].desa);
                    hidKecamatan.value = dataWilayah[provVal].kabupaten[kabVal].kecamatan[kecVal].nama.replace(/ \([0-9]+\)/, '');
                }
            }

            window.checkSelectedDesa = function() {
                const desaEl = document.getElementById('desa');
                const desaVal = desaEl.value; // Kemendagri code (kode desa)
                let desaNameRaw = desaEl.options[desaEl.selectedIndex].text;
                let desaName = desaNameRaw.replace(/ \([0-9]+\)/, '');
                
                if (!desaVal) {
                    villageCard.classList.add('hidden');
                    hidKodeDesa.value = '';
                    return;
                }

                hidKodeDesa.value = desaVal;
                hidNamaDesa.value = desaName;
                
                const provVal = document.getElementById('provinsi').value;
                const kabVal = document.getElementById('kabupaten').value;
                const kecVal = document.getElementById('kecamatan').value;

                dispNamaDesa.textContent = `Desa ${desaName}`;
                dispWilayahFull.textContent = `Kec. ${hidKecamatan.value}, ${hidKabupaten.value}, Prov. ${hidProvinsi.value.replace(/ \([0-9]+\)/, '')} (Kode: ${desaVal})`;
                
                villageCard.classList.remove('hidden');

                // Visual feedback only
                dispStatusBadge.className = 'px-3 py-1.5 bg-emerald-100 text-emerald-800 rounded-full text-xs font-bold flex items-center gap-1.5 shadow-sm border border-emerald-300';
                dispStatusIcon.textContent = '✅';
                dispStatusText.textContent = 'Referensi Sesuai';
                dispXosidNote.classList.remove('hidden');
            }

            // Form Submit Event
            const form = document.getElementById('form-amp-reg');
            const alertBox = document.getElementById('alert-box');
            const btnSubmit = document.getElementById('btn-submit');

            form.addEventListener('submit', (e) => {
                e.preventDefault();

                if (!hidKodeDesa.value) {
                    alertBox.className = 'p-4 rounded-2xl text-sm font-medium bg-red-100 text-red-800 border border-red-200 block';
                    alertBox.textContent = 'Harap pilih Desa dari hasil pencarian database XOSID terlebih dahulu.';
                    return;
                }

                btnSubmit.disabled = true;
                btnSubmit.textContent = 'Memproses Pendaftaran...';

                const formData = new FormData(form);
                const payload = {};
                formData.forEach((val, key) => payload[key] = val);

                fetch('/api/amp/register', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                })
                .then(res => res.json())
                .then(res => {
                    if (res.status === 'success') {
                        alertBox.className = 'p-4 rounded-2xl text-sm font-medium bg-emerald-100 text-emerald-800 border border-emerald-200 block';
                        alertBox.textContent = res.message;
                        setTimeout(() => {
                            window.location.href = res.redirect || '/dashboard';
                        }, 1200);
                    } else {
                        alertBox.className = 'p-4 rounded-2xl text-sm font-medium bg-red-100 text-red-800 border border-red-200 block';
                        alertBox.textContent = res.message || 'Terjadi kesalahan.';
                        btnSubmit.disabled = false;
                        btnSubmit.textContent = 'Kirim Pendaftaran Keanggotaan AMP →';
                    }
                })
                .catch(err => {
                    alertBox.className = 'p-4 rounded-2xl text-sm font-medium bg-red-100 text-red-800 border border-red-200 block';
                    alertBox.textContent = 'Gagal menghubungi server.';
                    btnSubmit.disabled = false;
                    btnSubmit.textContent = 'Kirim Pendaftaran Keanggotaan AMP →';
                });
            });
        });
    </script>
</body>
</html>
